import { Injectable, signal } from '@angular/core';

export type Lang = 'en' | 'fr';

@Injectable({
    providedIn: 'root'
})
export class TranslationService {
    currentLang = signal<Lang>('en');

    translations: Record<string, Record<Lang, string>> = {
        'nav.about': { en: 'About', fr: 'À propos' },
        'nav.skills': { en: 'Skills', fr: 'Compétences' },
        'nav.projects': { en: 'Projects', fr: 'Projets' },
        'nav.contact': { en: 'Contact', fr: 'Contact' },
        'hero.greeting': { en: 'Hello, I\'m', fr: 'Bonjour, je suis' },
        'hero.role': { en: 'Full-Stack Web Developer', fr: 'Développeur Web Full-Stack' },
        'hero.btn.projects': { en: 'View Projects', fr: 'Voir Projets' },
        'hero.btn.contact': { en: 'Contact Me', fr: 'Me Contacter' },
        'sect.about': { en: 'About Me', fr: 'À Propos de Moi' },
        'sect.skills': { en: 'Technical Skills', fr: 'Compétences Techniques' },
        'sect.projects': { en: 'Featured Projects', fr: 'Projets Réalisés' },
        'sect.edu': { en: 'Education & Experience', fr: 'Éducation & Expérience' },
        'sect.contact': { en: 'Get In Touch', fr: 'Contactez-moi' },
        'about.text1': {
            en: 'I am a passionate Full-Stack Web Developer based in Morocco, with a BTS in Web Development. I specialize in building robust and scalable applications using Angular and Spring Boot.',
            fr: 'Je suis un développeur web Full-Stack passionné basé au Maroc, titulaire d\'un BTS en Développement Web. Je me spécialise dans la création d\'applications robustes et évolutives avec Angular et Spring Boot.'
        },
        'about.text2': {
            en: 'My philosophy focuses on writing clean, performant, and secure code. I enjoy translating complex requirements into simple, elegant, and user-friendly interfaces. Whether it\'s a sleek frontend or a powerful backend API, I love the challenge of creating seamless web experiences.',
            fr: 'Ma philosophie se concentre sur l\'écriture d\'un code propre, performant et sécurisé. J\'aime traduire des exigences complexes en interfaces simples, élégantes et conviviales. Qu\'il s\'agisse d\'un frontend épuré ou d\'une API backend puissante, j\'aime le défi de créer des expériences web fluides.'
        },
        'projects.viewLive': { en: 'View Live', fr: 'Voir en direct' },
        'projects.viewCode': { en: 'View Code', fr: 'Voir Code' },
        'nav.cv': { en: 'CV', fr: 'CV' },
        'hero.cv': { en: 'Download CV', fr: 'Télécharger CV' },
        'contact.btn': { en: 'Send Message', fr: 'Envoyer Message' }
    };

    setLanguage(lang: Lang) {
        this.currentLang.set(lang);
        document.documentElement.lang = lang;
    }

    translate(key: string): string {
        return this.translations[key]?.[this.currentLang()] || key;
    }
}
